      ["suits", "STROJE"],
      ["skills", "UMIEJ\u0118TNO\u015ACI"],
      ["moves", "STEROWANIE"],
      ["tod", todLabel()],
      ["music", musLabel()],
      ["voice", voiceLabel()],
      ["gfx", gfxLabel()]
